/**
 * Connects to `url`, sends `messages` in order, reads as many back and closes (1000).
 *
 * Against an echo server the replies are the messages; any end of the connection before that is
 * the error (a refusal, `Closed` with the server's code, `Network`).
 * @throws {WsError}
 * @throws {UndraCallError} If the core panics, refuses or cancels the call, or cannot be reached.
 * @throws The `signal`'s reason (an `AbortError` by default) if it aborts the call.
 */
export async function wsEcho(
  url: string,
  messages: WsMessage[],
  core: UndraCore = UndraPlaygroundCore.core,
  signal?: AbortSignal,
): Promise<WsMessage[]> {
  const w = new UndraWriter();
  w.writeStr(url);
  vecWsMessage.encode(w, messages);
  try {
    const body = await core.call(
      { target: CallTarget.FreeFunction },
      UndraIds.Functions.wsEcho,
      w.finish(),
      signal,
    );
    return decodeValue(vecWsMessage, body);
  } catch (error) {
    throw UndraCallError.mapped(error, WsErrorCodec);
  }
}

/** Decodes every item of a core stream; a failure of the stream or of an item goes through `mapError`. */
async function* decodeStream<T>(
  source: AsyncIterable<Uint8Array>,
  codec: Codec<T>,
  mapError: (error: unknown) => unknown,
): AsyncGenerator<T, void, undefined> {
  try {
    for await (const body of source) yield decodeValue(codec, body);
  } catch (error) {
    throw mapError(error);
  }
}

